import * as THREE from 'three/webgpu';
import {
  texture,
  uv,
  mix,
  mul,
  color,
  vec2,
  attribute,
} from 'three/tsl';
import { gsap } from 'gsap';
import { createTextNode } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{imageUrl:string}} assets
 * @property {Array<Object>} cinematicPrimitives
 * @property {Array<Object>} textContent
 */

/**
 * @typedef {Object} NodeContext
 * @property {{textureLoader: {load:(url:string)=>THREE.Texture}}} textureLoader
 * @property {Object<string, Function>} primitives
 * @property {{fontAtlas:any}} fontAtlas
 */

/**
 * Create the feature‑triptych node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const root = new THREE.Group();
  root.position.set(0, 0, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);
  /** @type {Array<THREE.AnimationTarget>} */
  const _timelines = [];

  // ------------------------------------------------------------
  // Load shared resources
  // ------------------------------------------------------------
  const cardTexture = ctx.textureLoader.load(config.assets.imageUrl);
  cardTexture.flipY = false;

  // ------------------------------------------------------------
  // Helper: build a card (plane + disc + texts)
  // ------------------------------------------------------------
  const CARD_W = 1.5;
  const CARD_H = 1.9;
  const GAP = 0.25;
  const DISC_DIAM = 0.4;
  const DISC_R = DISC_DIAM / 2;
  const DISC_E = 0.05; // extrusion depth
  const PADDING = 0.375; // interior padding from top edge
  const ICON_GAP = 0.25;
  const TITLE_GAP = 0.125;

  const baseYTop = CARD_H / 2; // +0.95
  const discCenterY = baseYTop - PADDING - DISC_R; // vertical centre of the disc

  // Gradient node (vertical ramp)
  const gradNode = mix(
    color('#191921'),
    color('#121218'),
    uv().y
  );

  // Albedo node: texture multiplied by gradient
  const albedoNode = mul(texture(cardTexture), gradNode);

  // Card material (standard node material)
  const cardMaterial = new THREE.MeshStandardNodeMaterial({
    transparent: true,
    side: THREE.DoubleSide,
  });
  cardMaterial.colorNode = albedoNode;
  cardMaterial.roughness = 0.6;
  cardMaterial.metalness = 0.25;
  cardMaterial.clearcoat = 0.15;
  cardMaterial.clearcoatRoughness = 0.1;

  // Disc material (machined metal)
  const discMaterial = new THREE.MeshStandardNodeMaterial({
    color: new THREE.Color('#26262f'),
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
  });
  discMaterial.emissive = new THREE.Color('#ff2a38');
  discMaterial.emissiveIntensity = 1.6;

  // ------------------------------------------------------------
  // Build three cards
  // ------------------------------------------------------------
  const totalWidth = 3 * CARD_W + 2 * GAP; // 5.0
  const startX = -totalWidth / 2 + CARD_W / 2; // -1.75

  const cardsData = [
    {
      icon: '01',
      title: 'In-House Calibre',
      body: 'Every movement is designed, machined, and finished under one roof.',
    },
    {
      icon: '02',
      title: 'Five-Year Guarantee',
      body: 'Each piece is serviced free of charge for five years from delivery.',
    },
    {
      icon: '03',
      title: 'Hand-Finished Dials',
      body: 'Guilloche cut on a 1912 rose engine, one dial at a time.',
    },
  ];

  cardsData.forEach((data, i) => {
    const cardGroup = new THREE.Group();
    const cardX = startX + i * (CARD_W + GAP);
    cardGroup.position.set(cardX, 0, 0);
    root.add(cardGroup);

    // ----- Plane (card) -----
    const planeGeo = new THREE.PlaneGeometry(CARD_W, CARD_H);
    const planeMesh = new THREE.Mesh(planeGeo, cardMaterial.clone());
    // ensure each card has its own material instance for opacity handling
    planeMesh.material.transparent = true;
    planeMesh.material.opacity = 0; // start invisible for fade‑up
    cardGroup.add(planeMesh);

    // ----- Disc (icon seat) -----
    const discGeo = new THREE.CylinderGeometry(DISC_R, DISC_R, DISC_E, 32);
    const discMesh = new THREE.Mesh(discGeo, discMaterial.clone());
    discMesh.position.set(0, discCenterY, 0.01);
    discMesh.rotation.x = Math.PI / 2; // face forward
    cardGroup.add(discMesh);

    // ----- Glyph (icon text) -----
    const glyphNode = createTextNode({
      text: data.icon,
      font: ctx.fontAtlas,
      size: 20,
      weight: 700,
      color: '#ff2a38',
      align: 'center',
    });
    glyphNode.position.set(0, discCenterY, DISC_E / 2 + 0.001);
    cardGroup.add(glyphNode);

    // ----- Title text -----
    const titleY = discCenterY - DISC_R - ICON_GAP - 0.1; // rough offset
    const titleNode = createTextNode({
      text: data.title,
      font: ctx.fontAtlas,
      size: 20,
      weight: 600,
      color: '#e8ecf2',
      align: 'center',
    });
    titleNode.position.set(0, titleY, 0.02);
    cardGroup.add(titleNode);

    // ----- Body text -----
    const bodyY = titleY - 0.15 - TITLE_GAP;
    const bodyNode = createTextNode({
      text: data.body,
      font: ctx.fontAtlas,
      size: 13,
      weight: 400,
      color: '#e8ecf2',
      align: 'center',
      maxWidth: CARD_W - 0.3,
    });
    bodyNode.position.set(0, bodyY, 0.02);
    cardGroup.add(bodyNode);

    // --------------------------------------------------------
    // Initial stagger‑fade‑up animation (GSAP)
    // --------------------------------------------------------
    const originalY = cardGroup.position.y;
    const tl = gsap.timeline({ paused: true });
    tl.fromTo(
      planeMesh.material,
      { opacity: 0 },
      { opacity: 1, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
      0
    )
      .fromTo(
        cardGroup.position,
        { y: originalY + 0.2 },
        { y: originalY, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
        0
      );
    tl.delay(i * 0.08).play();
    _timelines.push(tl);

    // --------------------------------------------------------
    // Hover lift + emissive boost
    // --------------------------------------------------------
    const hoverTL = gsap.timeline({ paused: true });
    hoverTL.to(
      cardGroup.position,
      {
        y: originalY + 0.06,
        z: 0.12,
        duration: 0.18,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      },
      0
    );
    hoverTL.to(
      discMaterial,
      { emissiveIntensity: 2.2, duration: 0.18, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
      0
    );
    _timelines.push(hoverTL);

    // Store handlers on the group
    cardGroup.userData.handlers = {
      pointerover: () => hoverTL.play(),
      pointerout: () => hoverTL.reverse(),
    };
  });

  // ------------------------------------------------------------
  // Cleanup
  // ------------------------------------------------------------
  root.userData.cleanup = () => {
    _timelines.forEach((t) => t.kill());
    root.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => m.dispose());
          } else {
            obj.material.dispose();
          }
        }
      }
    });
  };

  return root;
}
